/*
 * A262892  Indices of nonbranching nodes in the infinite trunk (A259934) of
 *          the tree generated by edge-relation A049820(child) = parent.
 * https://oeis.org/A262892
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   search: sieve d(k), build the tree of edges k -> k - d(k) up to
 *            a limit L, mark the infinite trunk A259934 (nodes with
 *            descendants among the top W nodes), and list the 0-based trunk
 *            indices i (A259934 has offset 0) whose node A259934(i) has
 *            exactly one child (A060990 = 1)
 * Range:     u8 n <= 103, u16 n <= 4085, u32 n <= 4085, u64 n <= 4085,
 *            u128 n <= 4085, big any n
 * Validated: standard, pass, 101 terms through n = 4027 (2026-11-07)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stddef.h>

static uint64_t *A262892_res = 0;
static size_t A262892_nres = 0;

static void A262892_build(uint64_t L)
{
    const uint64_t W = 300;
    uint16_t *d = (uint16_t *)calloc((size_t)L + 1, sizeof(uint16_t));
    uint8_t *cc = (uint8_t *)calloc((size_t)L + 1, 1);
    int32_t *cnt = (int32_t *)calloc((size_t)L + 1, sizeof(int32_t));
    uint64_t i, j, n, k, idx;
    size_t cap = 0;

    for (i = 1; i <= L; i++)
        for (j = i; j <= L; j += i) d[j]++;

    for (n = L; n > L - W; n--) cnt[n] = 1;
    for (n = L; n >= 1; n--) {
        uint64_t p = n - d[n];
        if (cc[p] < 200) cc[p]++;
        cnt[p] += cnt[n];
    }

    free(A262892_res);
    A262892_res = 0;
    A262892_nres = 0;
    idx = 0; /* A259934 has offset 0: A259934(0) = 0 */
    for (k = 0; k <= L / 4; k++) {
        if (cnt[k] == (int32_t)W) {
            if (cc[k] == 1) {
                if (A262892_nres == cap) {
                    cap = cap ? cap * 2 : 1024;
                    A262892_res = (uint64_t *)realloc(A262892_res, cap * sizeof(uint64_t));
                }
                A262892_res[A262892_nres++] = idx;
            }
            idx++;
        }
    }
    free(d);
    free(cc);
    free(cnt);
}

seq_t a(idx_t n)
{
    static uint64_t L = 0;
    if (n < 1) return 0;
    while (n > A262892_nres) {
        L = L ? L * 2 : ((uint64_t)1 << 21);
        A262892_build(L);
        if (L > ((uint64_t)1 << 26)) break;
    }
    if (n > A262892_nres) return 0;
    return (seq_t)A262892_res[n - 1];
}
